// Compara os telefones sem formatacao e aceita o formato original ou o temporario do CRM.
const evento = $('When Executed by Another Workflow').first().json.evento ?? {};
const prep = $('Preparar telefones CRM').first().json ?? {};
const respostaPrincipal = $('Buscar lead pelo telefone').isExecuted ? $('Buscar lead pelo telefone').first().json : null;
const respostaFallback = $('Buscar lead pelo telefone original').isExecuted ? $('Buscar lead pelo telefone original').first().json : null;
const resposta = respostaFallback ?? respostaPrincipal ?? {};
const limpar = (v) => String(v ?? '').replace(/\D/g, '');
const telefonesAceitos = new Set([
  limpar(prep.telefone_original ?? evento.contato?.wa_id),
  limpar(prep.telefone_busca_principal ?? evento.contato?.wa_id)
].filter(Boolean));
const candidatos = Array.isArray(resposta)
  ? resposta
  : (resposta.leads ?? resposta.content ?? resposta.data ?? resposta.items ?? []);
const lead = (Array.isArray(candidatos) ? candidatos : [])
  .find((item) => telefonesAceitos.has(limpar(item.telefone ?? item.phone ?? item.whatsapp)));
return [{ json: { ...evento, crm: { lead_id: String(lead?.id ?? lead?.leadId ?? ''), atendimento_id: '' } } }];

// A busca pontual do CRM devolve um único cartão, em vez da lista inteira do painel.
// Se ainda não há lead, pulamos o HTTP. Se a API devolve 404, mantemos o mesmo
// contexto anterior: lead conhecido, mas atendimento não localizado.
const contexto = $('Selecionar lead exato').first().json;
const variaveis = $('Variaveis contexto CRM').first().json;
const leadId = String(contexto.crm?.lead_id ?? '');
let atendimento = {};

if (leadId && $('Buscar atendimento do lead no CRM').isExecuted) {
  const resposta = $('Buscar atendimento do lead no CRM').first().json;
  const status = Number(resposta.statusCode ?? 0);

  if (status === 200) {
    atendimento = resposta.body ?? {};
    // Nunca aceitar o cartão de outro lead nem tratar uma resposta quebrada
    // como se não existisse atendimento. Isso poderia liberar a IA indevidamente.
    if (!atendimento.atendimentoId || String(atendimento.leadId ?? '') !== leadId) {
      throw new Error('CARTAO_DE_ATENDIMENTO_INCOMPATIVEL_COM_LEAD');
    }
  } else if (status !== 404) {
    throw new Error('FALHA_NA_BUSCA_PONTUAL_DE_ATENDIMENTO_HTTP_' + status);
  }
}

const atendimentoId = String(atendimento.atendimentoId ?? '');
const statusAtendimento = String(atendimento.status ?? '').toUpperCase();
const modoAtendimento = String(atendimento.modoAtendimento ?? atendimento.modo ?? '').toUpperCase();
const iaAtivaCampo = atendimento.iaAtiva ?? atendimento.ia_ativa ?? atendimento.emIa ?? atendimento.em_ia ?? null;
const iaAtiva = typeof iaAtivaCampo === 'boolean'
  ? iaAtivaCampo
  : ['TRUE', '1', 'SIM', 'EM_IA', 'IA'].includes(String(iaAtivaCampo ?? '').trim().toUpperCase());
const statusIa = ['EM_IA', 'IA', 'BOT', 'AUTOMACAO', 'AUTOMACAO_IA'].includes(statusAtendimento) || modoAtendimento === 'IA' || iaAtiva;
const iaAutorizada = !atendimentoId || statusIa;

const memoriaContextWindowLength = Number(variaveis.memoria_context_window_length);
if (!Number.isFinite(memoriaContextWindowLength) || memoriaContextWindowLength <= 0) {
  throw new Error('MEMORIA_CONTEXT_WINDOW_LENGTH_NAO_CONFIGURADO');
}

const waId = String(contexto.contato?.wa_id ?? '').replace(/\D/g, '');
// A memória da IA pertence ao lead, não ao atendimento.
// Um novo atendimento do mesmo lead continua usando a conversa anterior.
const sessionId = leadId
  ? String(variaveis.session_prefix_lead ?? '') + leadId
  : String(variaveis.session_prefix_wa ?? '') + waId;

return [{ json: {
  ...contexto,
  crm: {
    ...contexto.crm,
    atendimento_id: atendimentoId,
    status_atendimento: statusAtendimento,
    modo_atendimento: modoAtendimento,
    ia_ativa: statusIa,
    ia_autorizada: iaAutorizada,
    contexto_localizado: Boolean(leadId && atendimentoId),
    origem_status_atendimento: atendimentoId ? 'LISTA_ATENDIMENTOS_CRM' : 'ATENDIMENTO_NAO_LOCALIZADO'
  },
  memoria: {
    tipo: 'POSTGRES_CHAT_MEMORY',
    session_id: sessionId,
    table: String(variaveis.memoria_tabela ?? ''),
    context_window_length: memoriaContextWindowLength
  }
} }];

// Ajuste temporario para o formato de telefone usado atualmente pelo CRM.
// Para celulares brasileiros, o CRM pode armazenar um 9 adicional depois do DDD.
const contexto = $('Variaveis contexto CRM').first().json;
const original = String(contexto.evento?.contato?.wa_id ?? '').replace(/\D/g, '');
let principal = original;

// So altera Brasil (55) com DDD + assinante de exatamente 8 digitos.
// Assinantes iniciados em 6, 7, 8 ou 9 sao tratados como celular.
if (original.startsWith('55') && original.length === 12) {
  const assinante = original.slice(4);
  if (/^[6-9]\d{7}$/.test(assinante)) {
    principal = original.slice(0, 4) + '9' + assinante;
  }
}

return [{ json: {
  ...contexto,
  telefone_original: original,
  telefone_busca_principal: principal
} }];
